// Phase 3 fixtures and count-table validation.
// Expected values are hand-derived from the rule definitions, not generated by the engine under test.
import { describe, expect, it } from 'vitest';
import type { Boundary, Model, RuleSpec } from '../../src/domain/contracts/model';
import { createEngine, type EngineCheckpoint } from '../../src/domain/engine/engine';
import { createStream, sessionSeed } from '../../src/domain/random/prng';
import { randomInitialize } from '../../src/domain/random/seeded';
import { caseCount, compileCountTable, validateCountTable, type CountTableRule } from '../../src/domain/rules/countTable';
import { validateModel } from '../../src/domain/model/validate';
import { lifeModel } from '../../src/data/presets';

const DEAD: Boundary = { kind: 'fixed-exterior', state: 0 };
const TORUS: Boundary = { kind: 'periodic' };

function model(rule: RuleSpec, w: number, h: number, set: Array<[number, number, number]> = [], boundary: Boundary = DEAD, states = 3, fill = 0): Model {
  const initial = new Uint8Array(w * h).fill(fill);
  for (const [x, y, s] of set) initial[y * w + x] = s;
  return {
    name: 't',
    width: w,
    height: h,
    stateCount: states,
    stateLabels: Array.from({ length: states }, (_, i) => `S${i}`),
    boundary,
    schedule: 'synchronous',
    rule,
    initial,
  };
}
const at = (m: { width: number }, cells: Uint8Array, x: number, y: number) => cells[y * m.width + x];

describe("SIM-13 Brian's Brain", () => {
  it('firing → refractory → ready; a ready cell with exactly two firing neighbors fires', () => {
    const m = model({ id: 'brians-brain/v1' }, 5, 5, [
      [1, 2, 1],
      [3, 2, 1],
      [2, 0, 2],
    ]);
    const e = createEngine(m);
    e.step();
    expect(at(m, e.cells, 1, 2)).toBe(2);
    expect(at(m, e.cells, 3, 2)).toBe(2);
    expect(at(m, e.cells, 2, 0)).toBe(0);
    expect(at(m, e.cells, 2, 2)).toBe(1); // exactly two firing neighbors
    expect(at(m, e.cells, 0, 0)).toBe(0); // ready, no firing neighbors
  });
  it('refractory neighbors do not count as firing', () => {
    const m = model({ id: 'brians-brain/v1' }, 5, 5, [
      [1, 2, 2],
      [3, 2, 2],
    ]);
    const e = createEngine(m);
    e.step();
    expect(at(m, e.cells, 2, 2)).toBe(0);
  });
  it('three firing neighbors do not fire a ready cell', () => {
    const m = model({ id: 'brians-brain/v1' }, 5, 5, [
      [1, 2, 1],
      [3, 2, 1],
      [2, 1, 1],
    ]);
    const e = createEngine(m);
    e.step();
    expect(at(m, e.cells, 2, 2)).toBe(0);
  });
});

describe('SIM-14 cyclic CA', () => {
  for (const neighborhood of ['moore-r1', 'von-neumann-r1'] as const) {
    it(`a uniform grid stays uniform (${neighborhood}) for every threshold`, () => {
      for (let t = 1; t <= (neighborhood === 'moore-r1' ? 8 : 4); t++) {
        for (const boundary of [TORUS, { kind: 'fixed-exterior', state: 2 } as Boundary]) {
          const m = model({ id: 'cyclic/v1', states: 4, threshold: t, neighborhood }, 6, 6, [], boundary, 4, 2);
          const e = createEngine(m);
          e.step(3);
          expect(e.cells.every((v) => v === 2)).toBe(true);
        }
      }
    });
  }
  it('threshold compares target-state counts only', () => {
    // State 0 cell with three neighbors in target state 1 advances at T=3; with state-2 neighbors it does not.
    const a = model(
      { id: 'cyclic/v1', states: 3, threshold: 3, neighborhood: 'moore-r1' },
      5,
      5,
      [
        [1, 1, 1],
        [2, 1, 1],
        [3, 1, 1],
      ],
      DEAD,
      3,
    );
    const ea = createEngine(a);
    ea.step();
    expect(at(a, ea.cells, 2, 2)).toBe(1);
    const b = model(
      { id: 'cyclic/v1', states: 3, threshold: 3, neighborhood: 'moore-r1' },
      5,
      5,
      [
        [1, 1, 2],
        [2, 1, 2],
        [3, 1, 2],
      ],
      DEAD,
      3,
    );
    const eb = createEngine(b);
    eb.step();
    expect(at(b, eb.cells, 2, 2)).toBe(0);
    // The last state wraps to 0: a state-2 cell (K=3) with 3 neighbors in state 0 advances.
    const c = model({ id: 'cyclic/v1', states: 3, threshold: 3, neighborhood: 'moore-r1' }, 5, 5, [[2, 2, 2]], DEAD, 3);
    const ec = createEngine(c);
    ec.step();
    expect(at(c, ec.cells, 2, 2)).toBe(0);
  });
});

describe('SIM-15/16 forest fire', () => {
  it('SIM-15: fire spreads one cell per generation; the source burns out', () => {
    const m = model({ id: 'forest-fire/v1', growth: 0, ignition: 0, neighborhood: 'moore-r1' }, 5, 3, [
      [1, 1, 2],
      [2, 1, 1],
      [3, 1, 1],
    ]);
    const e = createEngine(m, { transitionSeed: 'x' });
    e.step();
    expect([at(m, e.cells, 1, 1), at(m, e.cells, 2, 1), at(m, e.cells, 3, 1)]).toEqual([0, 2, 1]);
    e.step();
    expect([at(m, e.cells, 1, 1), at(m, e.cells, 2, 1), at(m, e.cells, 3, 1)]).toEqual([0, 0, 2]);
  });
  it('SIM-16: an empty lattice with p=1 becomes all trees, with no same-step ignition even at f=1', () => {
    const m = model({ id: 'forest-fire/v1', growth: 1, ignition: 1, neighborhood: 'von-neumann-r1' }, 8, 8);
    const e = createEngine(m, { transitionSeed: 'x' });
    e.step();
    expect(e.cells.every((v) => v === 1)).toBe(true);
    e.step(); // now every tree ignites by lightning (f = 1)
    expect(e.cells.every((v) => v === 2)).toBe(true);
  });
});

describe('SIM-17/18 spatial SIR', () => {
  it('SIM-17: β=0, γ=1: all infected recover, nobody new is infected', () => {
    const m = model({ id: 'spatial-sir/v1', beta: 0, gamma: 1, neighborhood: 'moore-r1' }, 6, 6, [
      [1, 1, 1],
      [4, 4, 1],
      [2, 3, 1],
    ]);
    const e = createEngine(m, { transitionSeed: 'x' });
    e.step();
    expect(e.metrics.counts).toEqual([33, 0, 3]);
    expect(e.metrics.incidence).toBe(0);
  });
  it('SIM-18: β=1, γ=1, isolated infected center: center recovers, its 8 neighbors are infected', () => {
    const m = model({ id: 'spatial-sir/v1', beta: 1, gamma: 1, neighborhood: 'moore-r1' }, 5, 5, [[2, 2, 1]]);
    const e = createEngine(m, { transitionSeed: 'x' });
    e.step();
    expect(at(m, e.cells, 2, 2)).toBe(2);
    for (let y = 1; y <= 3; y++) for (let x = 1; x <= 3; x++) if (x !== 2 || y !== 2) expect(at(m, e.cells, x, y)).toBe(1);
    expect(e.metrics.counts).toEqual([16, 8, 1]);
    expect(e.metrics.incidence).toBe(8);
  });
  it('infection probability is 1 − (1−β)^k', () => {
    // With β=0.5 and k=2, P = 0.75. Over many independent susceptible cells with exactly 2 infected
    // neighbors (von Neumann), the observed fraction must be close to 0.75.
    const w = 300,
      h = 3; // row 1: susceptible cells, rows 0 and 2: infected
    const cells: Array<[number, number, number]> = [];
    for (let x = 0; x < w; x++) {
      cells.push([x, 0, 1], [x, 2, 1]);
    }
    const m = model({ id: 'spatial-sir/v1', beta: 0.5, gamma: 0, neighborhood: 'von-neumann-r1' }, w, h, cells, { kind: 'fixed-exterior', state: 2 });
    let infected = 0,
      trials = 0;
    for (let seed = 0; seed < 20; seed++) {
      const e = createEngine(m, { transitionSeed: `s${seed}` });
      e.step();
      for (let x = 0; x < w; x++) {
        trials++;
        if (at(m, e.cells, x, 1) === 1) infected++;
      }
    }
    expect(Math.abs(infected / trials - 0.75)).toBeLessThan(0.02);
  });
});

describe('SIM-19 probability boundaries consume both draws', () => {
  it('p=f=0 changes nothing but still consumes exactly 2N draws per generation', () => {
    const m = model({ id: 'forest-fire/v1', growth: 0, ignition: 0, neighborhood: 'moore-r1' }, 7, 5, [[1, 1, 1]]);
    const seed = sessionSeed('42', 'transition');
    const e = createEngine(m, { transitionSeed: seed });
    e.step(3);
    expect(e.cells).toEqual(m.initial);
    const ref = createStream(seed);
    for (let i = 0; i < 3 * 2 * 35; i++) ref.next();
    expect(e.transitionState()).toEqual(ref.state());
  });
});

describe('SIM-20 every output stays within the declared state space', () => {
  const rules: Array<[RuleSpec, number]> = [
    [{ id: 'brians-brain/v1' }, 3],
    [{ id: 'cyclic/v1', states: 7, threshold: 2, neighborhood: 'von-neumann-r1' }, 7],
    [{ id: 'forest-fire/v1', growth: 0.05, ignition: 0.001, neighborhood: 'moore-r1' }, 3],
    [{ id: 'spatial-sir/v1', beta: 0.3, gamma: 0.1, neighborhood: 'moore-r1' }, 3],
    [
      {
        id: 'count-table/v1',
        states: 4,
        neighborhood: 'moore-r1',
        clauses: [{ currentStates: [0], counts: [{ state: 3, min: 2, max: 8 }], nextState: 3 }],
        fallback: { kind: 'state', state: 1 },
      },
      4,
    ],
  ];
  for (const [rule, K] of rules) {
    it(rule.id, () => {
      for (const boundary of [TORUS, { kind: 'fixed-exterior', state: K - 1 } as Boundary]) {
        const m = model(rule, 23, 17, [], boundary, K);
        m.initial = randomInitialize(m.initial, 23, 17, Array(K).fill(1 / K), 'init');
        const e = createEngine(m, { transitionSeed: 't' });
        for (let g = 0; g < 30; g++) {
          e.step();
          expect(e.cells.every((v) => v < K)).toBe(true);
          expect(e.metrics.counts.reduce((a, b) => a + b, 0)).toBe(23 * 17);
        }
      }
    });
  }
});

describe('reproducibility', () => {
  const fire = () => {
    const m = model({ id: 'forest-fire/v1', growth: 0.03, ignition: 0.0005, neighborhood: 'moore-r1' }, 32, 32, [], TORUS);
    m.initial = randomInitialize(m.initial, 32, 32, [0.4, 0.55, 0.05], 'i');
    return m;
  };
  it('REP-01: same state, semantics and seed give identical states and metrics for 1,000 generations', () => {
    const a = createEngine(fire(), { transitionSeed: 's' }),
      b = createEngine(fire(), { transitionSeed: 's' });
    for (let g = 0; g < 1000; g++) {
      a.step();
      b.step();
      expect(b.metrics).toEqual(a.metrics);
    }
    expect(b.cells).toEqual(a.cells);
  });
  it('REP-02: one 100-step call equals 100 single steps, including final PRNG state', () => {
    const a = createEngine(fire(), { transitionSeed: 's' }),
      b = createEngine(fire(), { transitionSeed: 's' });
    a.step(100);
    for (let i = 0; i < 100; i++) b.step();
    expect(b.cells).toEqual(a.cells);
    expect(b.transitionState()).toEqual(a.transitionState());
  });
  it('reset restores the initial cells and the initial random stream', () => {
    const a = createEngine(fire(), { transitionSeed: 's' });
    a.step(40);
    const after40 = new Uint8Array(a.cells);
    a.reset();
    expect(a.cells).toEqual(fire().initial);
    a.step(40);
    expect(a.cells).toEqual(after40);
  });
  it('REP-04: checkpoint at 123 → JSON → restore → 250 equals the uninterrupted run', () => {
    const ref = createEngine(fire(), { transitionSeed: 's' });
    ref.step(250);
    const a = createEngine(fire(), { transitionSeed: 's' });
    a.step(123);
    const json = JSON.stringify({ ...a.checkpoint(), cells: Array.from(a.checkpoint().cells) });
    const parsed = JSON.parse(json);
    const cp: EngineCheckpoint = { ...parsed, cells: Uint8Array.from(parsed.cells) };
    const b = createEngine(fire(), { transitionSeed: 'a different seed: the checkpoint state wins' });
    b.restore(cp);
    expect(b.generation).toBe(123);
    b.step(127);
    expect(b.cells).toEqual(ref.cells);
    expect(b.metrics).toEqual(ref.metrics);
  });
  it('restore rejects an incompatible checkpoint', () => {
    const a = createEngine(fire(), { transitionSeed: 's' });
    const cp = a.checkpoint();
    expect(() => createEngine(lifeModel('l', 32, 32, [])).restore(cp)).toThrow(/different rule family/);
    expect(() => a.restore({ ...cp, transition: null })).toThrow(/random-stream/);
    expect(() => a.restore({ ...cp, engineVersion: 'old/0' })).toThrow(/made by old/);
  });
  it('REP-06: lastDraws replays the recorded draws without advancing the live stream', () => {
    const m = model({ id: 'spatial-sir/v1', beta: 0.4, gamma: 0.3, neighborhood: 'moore-r1' }, 9, 9, [
      [4, 4, 1],
      [5, 4, 1],
    ]);
    const seed = sessionSeed('r', 'transition');
    const e = createEngine(m, { transitionSeed: seed });
    e.step();
    const before = e.transitionState();
    const i = 4 * 9 + 3; // (3,4): susceptible with one infected neighbor... and (4,4) infected
    const d = e.lastDraws(i)!;
    expect(e.transitionState()).toEqual(before);
    const ref = createStream(seed);
    for (let k = 0; k < 2 * i; k++) ref.next();
    expect(d).toEqual([ref.next(), ref.next()]);
    // The observed transition agrees with the recorded draw.
    expect(at(m, e.cells, 3, 4)).toBe(d[0] < 0.4 ? 1 : 0);
    const d2 = e.lastDraws(4 * 9 + 4)!;
    expect(at(m, e.cells, 4, 4)).toBe(d2[1] < 0.3 ? 2 : 1);
    // A second engine stepped once more is unaffected by inspection of the first.
    const f = createEngine(m, { transitionSeed: seed });
    f.step(2);
    e.step();
    expect(e.cells).toEqual(f.cells);
  });
});

describe('count-table/v1', () => {
  const life: CountTableRule = {
    id: 'count-table/v1',
    states: 2,
    neighborhood: 'moore-r1',
    clauses: [
      { currentStates: [0], counts: [{ state: 1, min: 3, max: 3 }], nextState: 1 },
      { currentStates: [1], counts: [{ state: 1, min: 2, max: 3 }], nextState: 1 },
    ],
    fallback: { kind: 'state', state: 0 },
  };
  it('Life written as a count table matches the Life engine exactly', () => {
    const base = lifeModel('l', 40, 30, [], TORUS);
    base.initial = randomInitialize(base.initial, 40, 30, [0.65, 0.35], 'q');
    const a = createEngine(base);
    const b = createEngine({ ...base, initial: new Uint8Array(base.initial), rule: life });
    for (let g = 0; g < 60; g++) {
      a.step();
      b.step();
      expect(b.cells).toEqual(a.cells);
    }
  });
  it('has the documented case counts (51,480 at the largest supported size)', () => {
    expect(caseCount(8, 8)).toBe(51480);
    expect(caseCount(2, 8)).toBe(18);
    expect(caseCount(3, 4)).toBe(45);
    expect(compileCountTable(life).cases).toBe(18);
  });
  it('rejects overlapping clauses even when they agree', () => {
    const r: CountTableRule = { ...life, clauses: [...life.clauses, { currentStates: [0], counts: [{ state: 1, min: 3, max: 4 }], nextState: 1 }] };
    const issues = validateCountTable(r);
    expect(issues.map((i) => i.code)).toContain('RULE_TABLE_OVERLAP');
    expect(issues.find((i) => i.code === 'RULE_TABLE_OVERLAP')!.message).toMatch(/Clauses 1 and 3/);
  });
  it('rejects unreachable constraints with an explanation', () => {
    const r: CountTableRule = {
      id: 'count-table/v1',
      states: 3,
      neighborhood: 'von-neumann-r1',
      clauses: [
        {
          currentStates: [0],
          counts: [
            { state: 1, min: 3, max: 4 },
            { state: 2, min: 2, max: 4 },
          ],
          nextState: 2,
        },
      ],
      fallback: { kind: 'keep-current' },
    };
    const issues = validateCountTable(r);
    expect(issues.map((i) => i.code)).toEqual(['RULE_TABLE_UNREACHABLE']);
    expect(issues[0].message).toMatch(/can never apply/);
  });
  it('rejects duplicate state constraints, bad ranges, bad states and too many clauses', () => {
    const codes = (r: CountTableRule) => validateCountTable(r).map((i) => i.code);
    expect(
      codes({
        ...life,
        clauses: [
          {
            currentStates: [0],
            counts: [
              { state: 1, min: 1, max: 2 },
              { state: 1, min: 3, max: 3 },
            ],
            nextState: 1,
          },
        ],
      }),
    ).toContain('RULE_TABLE_DUPLICATE_COUNT');
    expect(codes({ ...life, clauses: [{ currentStates: [0], counts: [{ state: 1, min: 4, max: 2 }], nextState: 1 }] })).toContain('RULE_TABLE_COUNT_RANGE');
    expect(codes({ ...life, clauses: [{ currentStates: [0], counts: [{ state: 1, min: 0, max: 9 }], nextState: 1 }] })).toContain('RULE_TABLE_COUNT_RANGE');
    expect(codes({ ...life, clauses: [{ currentStates: [2], counts: [], nextState: 1 }] })).toContain('RULE_TABLE_STATE_RANGE');
    expect(codes({ ...life, clauses: [{ currentStates: [], counts: [], nextState: 1 }] })).toContain('RULE_TABLE_CURRENT_EMPTY');
    expect(codes({ ...life, fallback: { kind: 'state', state: 5 } })).toContain('RULE_TABLE_FALLBACK');
    expect(codes({ ...life, states: 9 })).toContain('RULE_TABLE_STATES');
    const many = Array.from({ length: 257 }, () => ({ currentStates: [0], counts: [{ state: 1, min: 3, max: 3 }], nextState: 1 }));
    expect(codes({ ...life, clauses: many })).toContain('RULE_TABLE_CLAUSE_LIMIT');
  });
  it('keep-current default leaves unmatched cells unchanged', () => {
    const r: CountTableRule = {
      id: 'count-table/v1',
      states: 3,
      neighborhood: 'moore-r1',
      clauses: [{ currentStates: [0], counts: [{ state: 2, min: 1, max: 8 }], nextState: 2 }],
      fallback: { kind: 'keep-current' },
    };
    const m = model(
      r,
      5,
      5,
      [
        [2, 2, 2],
        [0, 0, 1],
      ],
      DEAD,
      3,
    );
    const e = createEngine(m);
    e.step();
    expect(at(m, e.cells, 0, 0)).toBe(1); // unmatched: kept
    expect(at(m, e.cells, 1, 1)).toBe(2); // neighbor of the state-2 cell
    expect(at(m, e.cells, 4, 4)).toBe(0);
  });
  it('the large sparse form (8 states, Moore) compiles and runs', () => {
    const r: CountTableRule = {
      id: 'count-table/v1',
      states: 8,
      neighborhood: 'moore-r1',
      clauses: [{ currentStates: [0, 1, 2, 3, 4, 5, 6], counts: [{ state: 7, min: 1, max: 8 }], nextState: 7 }],
      fallback: { kind: 'keep-current' },
    };
    const t = compileCountTable(r);
    expect(t.dense).toBeNull();
    expect(t.cases).toBe(51480);
    const m = model(
      r,
      6,
      6,
      [
        [3, 3, 7],
        [0, 0, 2],
      ],
      DEAD,
      8,
    );
    const e = createEngine(m);
    e.step();
    expect(at(m, e.cells, 2, 2)).toBe(7);
    expect(at(m, e.cells, 0, 0)).toBe(2);
  });
});

describe('validation of new families', () => {
  it('reports bad parameters', () => {
    const codes = (rule: RuleSpec, states = 3) => validateModel(model(rule, 5, 5, [], DEAD, states)).map((i) => i.code);
    expect(codes({ id: 'forest-fire/v1', growth: 1.2, ignition: 0, neighborhood: 'moore-r1' })).toContain('RULE_PROBABILITY');
    expect(codes({ id: 'spatial-sir/v1', beta: Number.NaN, gamma: 0, neighborhood: 'moore-r1' })).toContain('RULE_PROBABILITY');
    expect(codes({ id: 'cyclic/v1', states: 3, threshold: 5, neighborhood: 'von-neumann-r1' })).toContain('RULE_CYCLIC_THRESHOLD');
    expect(codes({ id: 'cyclic/v1', states: 17, threshold: 1, neighborhood: 'moore-r1' }, 17)).toContain('RULE_CYCLIC_STATES');
    expect(codes({ id: 'brians-brain/v1' }, 2)).toContain('STRUCT_STATE_COUNT');
  });
  it('warns that an infected exterior makes extinction non-absorbing', () => {
    const m = model({ id: 'spatial-sir/v1', beta: 0.2, gamma: 0.1, neighborhood: 'moore-r1' }, 5, 5, [[2, 2, 1]], { kind: 'fixed-exterior', state: 1 });
    expect(validateModel(m).map((i) => i.code)).toContain('EDU_INFECTED_EXTERIOR');
  });
});
